// สร้างข้อความเตือนจากผล Check Temp Bounds — โค้ดล้วน ไม่มี AI ไม่มีค่า token
// เกาะไปกับ Telemetry Sync ที่รันทุก 15 นาที จึงรู้เร็วกว่ารายงาน AI ทุก 4 ชม.ถึง 16 เท่า
// (เจอจริง 8 ก.ย.: เบียร์หลุดต่ำกว่าขีดล่างยีสต์ตั้งแต่ ~09:00 แต่กว่าจะรู้คือรายงาน 18:01)
const COLOR = { sensor_stale: 0x95a5a6, controller_lag: 0xe74c3c, rapid_change: 0xe74c3c,
                yeast_low: 0xe67e22, yeast_high: 0xe67e22,
                band_low: 0xf1c40f, band_high: 0xf1c40f, arrived: 0x2ecc71 };
// ดันให้เข้ามาในช่วงยีสต์ 0.5°C ไม่ใช่จ่อขอบพอดี กันแกว่งออกอีกรอบทันที
const INSIDE_MARGIN_C = 0.5;
// จำกัดการขยับต่อครั้ง — ข้อเสนอมาจากสูตรคำนวณ ไม่ใช่คนดูของจริง อย่าให้สั่งกระโดดไกล
const MAX_NUDGE_C = 2.0;

function f(v, n) { return v == null ? '-' : Number(v).toFixed(n); }

const results = [];
$input.all().forEach((it) => {
  const d = it.json;
  const pill = d.pill_c != null ? Number(d.pill_c) : null;
  const tgt = d.target_c != null ? Number(d.target_c) : null;
  let title, lines = [], wantPill = null;

  switch (d.alert_kind) {
    case 'sensor_stale':
      title = '📡 เซ็นเซอร์เงียบ — ' + d.beer_name;
      lines.push('Pill เงียบมา ' + f(d.pill_age_h, 1) + ' ชม. · ตู้ควบคุม ' + f(d.ctrl_age_h, 1) + ' ชม.');
      lines.push('ค่าที่ระบบใช้วิเคราะห์ตอนนี้เป็นข้อมูลค้าง — เช็คแบต Pill / WiFi / ปลั๊กตู้ แล้วดูใน RAPT portal ว่า device ยัง online ไหม');
      break;
    case 'controller_lag':
      title = '🔴 ตู้ควบคุมไล่อุณหภูมิไม่ถึงเป้า — ' + d.beer_name;
      lines.push('ตู้ ' + f(d.ctrl_c, 2) + '°C ห่างจาก target ' + f(d.target_c, 2) + '°C อยู่ ' + f(d.ctrl_dev_c, 2) + '°C มาเกิน 1 ชม.และไม่ลดลง');
      lines.push('ไม่ใช่การไล่อุณหภูมิตามคำสั่งปกติ — ไปดูของจริง: คอมเพรสเซอร์ทำงานไหม ประตูปิดสนิทไหม ของในตู้แน่นเกินไปหรือเปล่า');
      lines.push('**อย่าเพิ่งปรับ target** เพราะปัญหาไม่ได้อยู่ที่ค่าที่ตั้ง');
      break;
    case 'rapid_change':
      title = '🔴 อุณหภูมิเบียร์เปลี่ยนเร็วผิดปกติ — ' + d.beer_name;
      lines.push('Pill ขยับ ' + f(d.pill_move_1h_c, 2) + '°C ใน 1 ชม. ทั้งที่ target ไม่ได้เปลี่ยน (ปกติไม่เกิน 1.5°C/ชม.)');
      lines.push('ล่าสุด ' + f(d.pill_c, 2) + '°C — เปิดประตูตู้ค้างไว้หรือเปล่า หรือระบบทำความเย็น/ฮีตเตอร์มีปัญหา');
      break;
    case 'yeast_low':
      title = '⚠️ อุณหภูมิเบียร์ต่ำกว่าที่ยีสต์รองรับ — ' + d.beer_name;
      lines.push('เบียร์ ' + f(d.pill_c, 2) + '°C ต่ำกว่าขีดล่าง ' + f(d.yeast_min, 0) + '°C อยู่ ' + f(Number(d.yeast_min) - pill, 2) + '°C');
      lines.push('เสี่ยงยีสต์ทำงานช้าลง ตกก้นก่อนกินน้ำตาลหมด หรือเก็บ diacetyl ไม่หมด');
      wantPill = Number(d.yeast_min) + INSIDE_MARGIN_C;
      break;
    case 'yeast_high':
      title = '⚠️ อุณหภูมิเบียร์สูงกว่าที่ยีสต์รองรับ — ' + d.beer_name;
      lines.push('เบียร์ ' + f(d.pill_c, 2) + '°C สูงกว่าขีดบน ' + f(d.yeast_max, 0) + '°C อยู่ ' + f(pill - Number(d.yeast_max), 2) + '°C');
      lines.push('เสี่ยง fusel alcohol (กลิ่นแสบ ดื่มแล้วปวดหัว) และ ester แรงเกินสไตล์');
      wantPill = Number(d.yeast_max) - INSIDE_MARGIN_C;
      break;
    case 'band_low':
    case 'band_high': {
      // ช่วงที่ผู้หมักตั้งเองผ่าน /ferment_band — เตือนแบบ "เฝ้าดู" เพราะยังไม่หลุดสเปกยีสต์
      const lo = Number(d.band_low), hi = Number(d.band_high);
      const below = d.alert_kind === 'band_low';
      title = '👀 อุณหภูมิเบียร์หลุดช่วงที่ตั้งไว้ — ' + d.beer_name;
      lines.push('เบียร์ ' + f(d.pill_c, 2) + '°C ' + (below ? 'ต่ำกว่า' : 'สูงกว่า') + 'ช่วงที่ตั้งไว้ '
        + f(lo, 2) + '-' + f(hi, 2) + '°C อยู่ ' + f(below ? lo - pill : pill - hi, 2) + '°C');
      lines.push(d.yeast_min != null
        ? ('(ยังอยู่ในช่วงที่ยีสต์รองรับ ' + f(d.yeast_min, 0) + '-' + f(d.yeast_max, 0) + '°C จึงยังไม่ถึงขั้นอันตราย)')
        : '(ไม่มีข้อมูลช่วงยีสต์มาเทียบ)');
      // เล็งกลางช่วง ไม่ใช่จ่อขอบ จะได้ไม่หลุดออกอีกทันทีที่แกว่งนิดเดียว
      wantPill = (lo + hi) / 2;
      break;
    }
    case 'arrived':
      title = '✅ อุณหภูมิเบียร์นิ่งแล้ว — ' + d.beer_name;
      lines.push('เบียร์นิ่งที่ ' + f(d.pill_c, 2) + '°C (ขยับ ' + f(d.pill_move_1h_c, 2) + '°C ใน 1 ชม.ล่าสุด) หลังตั้ง target ' + f(d.target_c, 2) + '°C มา ' + f(d.tgt_stable_h, 1) + ' ชม.');
      lines.push('ถึงที่หมายแล้ว เริ่มนับเวลาของเฟสนี้ได้');
      break;
    default:
      return;
  }

  // target ใหม่แบบ "ขยับสัมพัทธ์" — ไม่ต้องรู้ส่วนต่าง Pill-ตู้เลย เพราะอยากให้เบียร์ขึ้นเท่าไหร่
  // ก็ขยับ target ขึ้นเท่านั้น ส่วนต่างหักล้างกันไปเอง (ต่างจากการแปลงแบบสัมบูรณ์ที่ต้องใช้
  // stable_gap_c ซึ่งมักไม่มีค่าในช่วง 2 ชม.แรกหลังปรับ target)
  // เสนอขยับได้เฉพาะตอนตู้ไล่ถึง target แล้วจริง — ถ้ายังไล่ไม่ถึง เบียร์กำลังจะขยับเองอยู่แล้ว
  // การขยับ target ซ้ำตอนนั้นจะ over-correct (เจอจริง 8 ก.ย.: ตู้ 15.98 vs target 16.50 ถ้าไล่
  // ถึง 16.50 เบียร์จะขึ้นไป ~18.2 เองโดยไม่ต้องทำอะไร)
  const ctrlSettled = d.ctrl_c != null && tgt != null && Math.abs(Number(d.ctrl_c) - tgt) <= 0.5;
  let buttonTarget = null;
  if (wantPill != null && !ctrlSettled) {
    lines.push('⏳ ยังไม่เสนอปรับ target — ตู้อยู่ ' + f(d.ctrl_c, 2) + '°C ยังไล่ไม่ถึง target ' + f(tgt, 2) + '°C เบียร์อาจขยับเข้าที่เองเมื่อตู้ถึงเป้า');
  }
  if (wantPill != null && ctrlSettled && pill != null && tgt != null) {
    const nudge = Math.max(-MAX_NUDGE_C, Math.min(MAX_NUDGE_C, wantPill - pill));
    const t = Number((tgt + nudge).toFixed(2));
    if (Math.abs(t - tgt) >= 0.5 && t >= 0 && t <= 30) buttonTarget = t;
  }
  if (buttonTarget != null) {
    lines.push('🌡️ เสนอปรับ target ตู้เป็น ' + f(buttonTarget, 2) + '°C (ขยับ ' + (buttonTarget > tgt ? '+' : '') + f(buttonTarget - tgt, 2) + '°C เพื่อดันเบียร์ไปที่ ~' + f(wantPill, 2) + '°C)');
  }

  results.push({
    json: {
      batch_id: d.batch_id,
      alert_kind: d.alert_kind,
      button_target_c: buttonTarget,
      embeds: [{
        title: title.length > 256 ? title.slice(0, 255) + '…' : title,
        color: COLOR[d.alert_kind] || 0x95a5a6,
        description: lines.join('\n').slice(0, 4096),
        footer: { text: 'เฟส ' + (d.current_phase || '-') + ' · ตรวจทุก 15 นาทีโดย Temp Guard' }
      }]
    }
  });
});
return results;
